<div class="toolbar"><p class="muted">Different students. The right fees. No hard-coded amounts.</p><a class="button" href="<?= e(url('fee-types')) ?>">Manage fee types →</a></div><section class="panel"><h2>Configured fee structures</h2><div class="table-wrap"><table><thead><tr><th>Academic year</th><th>Term</th><th>Class</th><th>Student type</th><th class="num">Total</th><th></th></tr></thead><tbody><?php if(!$structures) emptyRow(6); foreach($structures as $s): ?><tr><td><?= e($s['year_name']) ?></td><td><?= e($s['term_name']) ?></td><td><?= e($s['class_name']) ?></td><td><span class="badge neutral"><?= e($s['type_name']) ?></span></td><td class="num"><?= money($s['total']??0) ?></td><td><a href="<?= e(url('fees',['id'=>$s['id']])) ?>">Manage items →</a></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if($selected): ?><section class="panel"><h2>Fee items · structure #<?= e($selected['id']) ?></h2><p class="muted">Saving an existing fee type replaces its amount for future invoices. Issued invoices are unchanged.</p><table><thead><tr><th>Fee type</th><th class="num">Amount</th><th></th></tr></thead><tbody><?php if(!$items) emptyRow(3,'Add at least one fee item before billing.'); foreach($items as $i): ?><tr><td><?= e($i['name']) ?></td><td class="num"><?= money($i['amount']) ?></td><td><?php startForm('fee.remove',['fee_structure_id'=>$selected['id'],'fee_type_id'=>$i['fee_type_id']],'inline'); ?><button class="button danger" data-confirm="Remove this fee from future invoices?">Remove</button></form></td></tr><?php endforeach ?></tbody></table><?php startForm('fee.item',['fee_structure_id'=>$selected['id']]); selectField('fee_type_id','Fee type','fee_types'); field('amount','Amount · '.$school['currency'],'number'); endForm('Save fee item'); ?></section><?php endif ?>
